import csv
ids={
 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8':'temp',
 '5b98cbc1-fd25-5d8c-a96e-c3de49819174':'cool',
 'b7f22e0c-833d-5373-87e1-51e1cb26f038':'heat',
}
data={k:{} for k in ['temp','cool','heat']}
with open(VALUES_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        if row['timeseries_id'] in ids and row['timestamp'].startswith('2018-04-12'):
            data[ids[row['timeseries_id']]][row['timestamp']]=float(row['value'])
ts=sorted(data['temp'])
print('hours temp:',len(ts),'cool:',len(data['cool']),'heat:',len(data['heat']))
viol=0
for t in ts:
    if t in data['cool'] and t in data['heat']:
        tv=data['temp'][t]; c=data['cool'][t]; h=data['heat'][t]
        v = tv < h or tv > c
        if v: viol+=1
        print(t,tv,'heat',h,'cool',c,'VIOL' if v else '')
print('violations',viol)
